\section{کمزور حلن ہنٛز موجوٗدگی تہٕ اَکٲیی ہنٛد ثبوٗت خاکہٕ}

أسؠ چھِ اَکِس محدود ڈومین $\Omega\subset\mathbb{R}^n$ پؠٹھ اَکِس لینیئر ایلیپٹک آپریٹرس خٲطرٕ سُموٗت باؤنڈری سٟتؠ باؤنڈری ویلیو پرابلمس پؠٹھ غور کران:
\begin{equation}\label{eq:elliptic}
 -\Delta u + c u = f \quad\text{in }\Omega.
\end{equation}
ییٚتہِ $c\in L^\infty(\Omega)$ چھُ تقریبن پرٛتھ جایہِ $c(x)\ge c_0>0$ پوٗرٕ کران، تہٕ $f\in L^2(\Omega)$ چھُ۔ کمزور فارمولیشن چھِ یِتھ پٲٹھؠ پران: $u\in H^1_0(\Omega)$ یِتھ پٲٹھؠ ژھٲنٛڈِو زِ
\[
a(u,v)=\int_\Omega (\nabla u\cdot\nabla v + c\,u v)\,dx = \int_\Omega f v\,dx,\qquad\forall v\in H^1_0(\Omega).
\]

\begin{theorem}[کمزور حلن ہنٛز اَکٲیی]\label{thm:uniqueness}
اگر $u\in H^1_0(\Omega)$ کمزور معنَس مَنٛز $f\equiv 0$ سٟتؠ \eqref{eq:elliptic} پوٗرٕ چھُ کران، تیٚلہِ چھُ $u\equiv 0$۔
\end{theorem}

\begin{proof}
معیٲری انرجی میتھڈ چھُ لاگوٗ گژھان۔ فرض کٔرِو $u$ چھُ ہوموجینس کمزور پرابلم حل کران تہٕ $v=u$ سٟتؠ چھُ ٹیسٹ کران۔ کوئرسِوِٹی اِستِمال کٔرِتھ چھِ أسؠ حٲصِل کران
\begin{equation}\label{eq:coercive}
a(u,u)=\int_\Omega |\nabla u|^2 + c|u|^2\,dx \ge \min(1,c_0)\|u\|_{H^1_0(\Omega)}^2.
\end{equation}
چونکہِ دۄچھنہِ طَرف چھُ صِفر، \eqref{eq:coercive} چھُ اِشارٕ کران زِ $u=0$ a.e. یہِ چھُ اَکٲیی ہنٛد دلیٖل مُکمل کران۔
\end{proof}

